visible = { NOT = { exists = power_bloc power_bloc ?= { has_identity = identity:identity_aor1776_imperial_federation } } }

possible = { NOT = { exists = power_bloc power_bloc ?= { has_identity = identity:identity_aor1776_imperial_federation } } }
}

